(target: any, defaults: any) => {
  if (!isPlainObject(defaults)) return;

  for (const k of Object.keys(defaults)) {
    const dv = defaults[k];
    const tv = target[k];

    if (tv === undefined) {
      target[k] = deepClone(dv);
      continue;
    }

    if (isPlainObject(tv) && isPlainObject(dv)) {
      deepMergeIfUndefined(tv, dv);
