(item: any): string => {
  if (item == null) return '';
  if (item == undefined) return '';

  // If already constructor
  if (typeof item === 'function') {
    return CLASS.getName(item) || '';
  }

  if (typeof item !== 'object') {
    return '';
  }

  // If instance
  const classFn = item.constructor;
  if (typeof classFn === 'function') {
    return CLASS.getName(classFn) || '';
  }

  return '';
}

